window.docContents[6].resolve({"/Hoare/#Hoare-Logic--Hoare___-Hoare-Logic___-Part-I--Proof-Rules":{"contents":"\n\nWe want to be able to prove Hoare triples formally.Here's our plan:* introduce one \"proof rule\" for each Imp syntactic form* plus a couple of \"structural rules\" that help glue proofs\n    together* prove these rules correct in terms of the definition of\n    ValidHoareTriple* prove programs correct using these proof rules, without ever\n    unfolding the definition of ValidHoareTriple\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n","context":"Hoare Logic\u0009Hoare: Hoare Logic, Part I","header":"4.4. Proof Rules","id":"/Hoare/#Hoare-Logic--Hoare___-Hoare-Logic___-Part-I--Proof-Rules"},"/Hoare2/#Hoare-Logic--Hoare2___-Hoare-Logic___-Part-II--Formal-Decorated-Programs":{"contents":"Now that this section has become standard material, the\nwriting could be improved :-)\n\n\n\nWith a little more work, we can formalize the definition of\nwell-formed decorated programs and automate the boring mechanical\nsteps in proving that the decorations are correct.\n\n\n\n\n\n\n\n","context":"Hoare Logic\u0009Hoare2: Hoare Logic, Part II","header":"5.2. Formal Decorated Programs","id":"/Hoare2/#Hoare-Logic--Hoare2___-Hoare-Logic___-Part-II--Formal-Decorated-Programs"}});